import{_ as r,o as t,c as o,a5 as a}from"./chunks/framework.BZzouRtU.js";const c="/study/images/browser/ring-buffer-cursors.svg",d="/study/images/browser/ring-buffer-publication.svg",m=JSON.parse('{"title":"リングバッファとSPSCキュー — 満杯・折り返し・受け渡し","description":"","frontmatter":{"title":"リングバッファとSPSCキュー — 満杯・折り返し・受け渡し","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"固定長の配列を先頭と末尾でつなぎ、読み書きの位置で空と満杯を区別する。書き手と読み手が一人ずつの共有キューで、値を公開し、読み終えた枠を再利用する順序を図解する。","aliases":["リングバッファ","ring buffer","circular buffer","SPSC","single producer single consumer","FIFO","cursor","キュー","満杯","折り返し","バックプレッシャー"],"verification":"LinuxのCircular Buffers文書とECMAScriptのAtomics・メモリモデルに照合（2026-11-05）"}},"headers":[],"relativePath":"browser/spsc-ring-buffer.md","filePath":"browser/spsc-ring-buffer.md"}'),s={name:"browser/spsc-ring-buffer.md"};function i(n,e,l,u,f,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="リングバッファとspscキュー-—-満杯・折り返し・受け渡し" tabindex="-1">リングバッファとSPSCキュー — 満杯・折り返し・受け渡し <a class="header-anchor" href="#リングバッファとspscキュー-—-満杯・折り返し・受け渡し" aria-label="Permalink to &quot;リングバッファとSPSCキュー — 満杯・折り返し・受け渡し&quot;">​</a></h1><p><strong>リングバッファ</strong>は固定長の配列を、末尾の次が先頭につながるものとして使う方式です。キューとして使うと、入れた順に取り出す <strong>FIFO</strong>（first in, first out）になります。例えば別の処理が作った音声サンプルや読み込み済みのアセットを順番に渡すとき、渡し先が一時的に遅れても、決めた件数まで待ち行列に置けます。<a href="https://docs.kernel.org/core-api/circular-buffers.html#what-is-a-circular-buffer" target="_blank" rel="noreferrer">LinuxのCircular Buffers</a>、<a href="/study/game/asset-loading.html">ゲームのアセット読み込み</a></p><h2 id="読み位置と書き位置で空と満杯を見分ける" tabindex="-1">読み位置と書き位置で空と満杯を見分ける <a class="header-anchor" href="#読み位置と書き位置で空と満杯を見分ける" aria-label="Permalink to &quot;読み位置と書き位置で空と満杯を見分ける&quot;">​</a></h2><p>4枠の配列を使います。次に取り出す位置を <code>R</code>、次に書く候補の位置を <code>W</code> とします。どちらも最初は0です。位置を1つ進める式は <code>next(i) = (i + 1) % 4</code> で、添字3の次は0になります。データは <code>R</code> から <code>W</code> の手前までを円を描くようにたどった範囲です。</p><table tabindex="0"><thead><tr><th>状態</th><th>判定</th><th>操作したとき</th></tr></thead><tbody><tr><td>空</td><td><code>R === W</code></td><td>取り出す値がなく、<code>R</code> を進めない</td></tr><tr><td>満杯</td><td><code>next(W) === R</code></td><td>挿入を断り、値を書かず <code>W</code> も進めない</td></tr><tr><td>挿入できる</td><td><code>next(W) !== R</code></td><td><code>W</code> の枠に書き、<code>W</code> を進める</td></tr><tr><td>取り出せる</td><td><code>R !== W</code></td><td><code>R</code> の枠から読み、<code>R</code> を進める</td></tr></tbody></table><p>満杯でも挿入して <code>W</code> を進めると <code>R === W</code> になり、位置だけでは空と見分けられなくなります。この方式では常に少なくとも1枠を空け、4枠で3件まで保持します。空ける枠はカーソルとともに移ります。別の実装では件数などを記録し、4枠すべてを使う設計もあります。<a href="https://docs.kernel.org/core-api/circular-buffers.html#what-is-a-circular-buffer" target="_blank" rel="noreferrer">LinuxのCircular Buffers</a></p><figure class="study-figure"><img src="'+c+'" alt="4枠のリングバッファに10、20、30を入れると満杯になり、40の挿入は断られる。10を取り出して40を枠3に書くと書き位置は0へ戻る。次に20を取り出し、空いた枠0に50を書く。取り出し順は30、40、50のまま。" width="760" height="1300" loading="lazy"><figcaption>枠番号と取り出し順は、書き位置が折り返すと異なります。図の「—」はキューに含まれない枠です。<a href="/study/images/browser/ring-buffer-cursors.svg" target="_blank" rel="noopener noreferrer">カーソルと折り返しの図を拡大</a></figcaption></figure><p>10、20、30を入れると <code>R=0, W=3</code> で満杯です。40の挿入をいったん断り、10を取り出して <code>R=1</code> にしてから40を挿入すると、40は枠3に入り、<code>W</code> が0に戻ります。この時点では <code>next(0) === R</code> なので再び満杯です。20を取り出して空きを作ってから50を入れると、10が入っていた枠0を再利用し、<code>R=2, W=1</code> になります。そこから読む順は枠2、3、0なので、30、40、50です。取り出すときに残っている要素を移動する必要はありません。読み終えた枠に古い値が残っていても、その枠がキューの範囲外なら取り出しの対象から外れます。</p><h2 id="一人ずつなら更新するカーソルを分けられる" tabindex="-1">一人ずつなら更新するカーソルを分けられる <a class="header-anchor" href="#一人ずつなら更新するカーソルを分けられる" aria-label="Permalink to &quot;一人ずつなら更新するカーソルを分けられる&quot;">​</a></h2><p><strong>SPSC</strong>（single producer, single consumer）は、書き手と読み手が一人ずつという条件です。書き手だけが <code>W</code> を更新し、読み手だけが <code>R</code> を更新します。二人の書き手が同じ <code>W</code> を読み、同じ枠に書く事態を、書き手を一人に限定して防ぎます。二人以上で役割を分担するキューには、枠を取り合わないための別の設計が必要です。<a href="https://docs.kernel.org/core-api/circular-buffers.html" target="_blank" rel="noreferrer">LinuxのCircular Buffers</a>、<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a></p><p>ブラウザで別々のWorkerが同じキューを操作する場合は、<code>SharedArrayBuffer</code> にカーソルとデータ枠を置きます。実践の <code>Int32Array</code> は、添字0に <code>R</code>、添字1に <code>W</code>、添字2〜5にデータを置く24バイトの構成です。相手のカーソルは <code>Atomics.load()</code> で読み、自分のカーソルは処理が終わってから <code>Atomics.store()</code> で進めます。カーソルの更新には二つの役割があります。<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>、<a href="/study/browser/shared-memory-atomics.html">Web Workerと共有メモリの同期</a></p><ul><li><strong>値の公開</strong>。書き手は満杯かを確認し、枠に値を書いてから <code>W</code> を進めます。読み手は <code>W</code> を読み、空でなければ <code>R</code> の枠の値を取得します。</li><li><strong>読み終えた枠の解放</strong>。読み手は枠から値を取得し終えてから <code>R</code> を進めます。書き手は <code>R</code> を読み、満杯でなければ <code>W</code> の枠に書きます。この確認で、読み手がまだ使っている枠を追い越さずに済みます。</li></ul><figure class="study-figure"><img src="'+d+'" alt="書き手は枠に値を書いた後でWをアトミックに更新する。読み手がその更新を確認してから枠を読む。読み手は枠を読み終えた後でRをアトミックに更新する。書き手がその更新を確認して空きを判断し、後で枠を再利用する。" width="760" height="1160" loading="lazy"><figcaption>書き手から読み手には値の準備ができたことを、読み手から書き手には読み終えた範囲を伝えます。<a href="/study/images/browser/ring-buffer-publication.svg" target="_blank" rel="noopener noreferrer">公開と枠の再利用の図を拡大</a></figcaption></figure><p>JavaScriptのアトミックな読み書きは逐次一貫（sequentially consistent）です。同じカーソルの <code>load</code> が <code>store</code> による更新を読んだとき、両者は同期します。この関係と各Workerの中の操作順をつなげると、値の書き込みが値の読み取りに先行し、値の読み取りが同じ枠への次の書き込みに先行します。データ枠はこの手順で使用権を渡すので、実践ではデータ自体を通常の <code>Int32Array</code> の読み書きで扱えます。表示のために第三の処理が並行実行中のデータ枠を直接読むと、同じ手順で保護されないため、共有実験の表示にはWorkerから返った結果を使います。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.load" target="_blank" rel="noreferrer">ECMAScriptのAtomics.load</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.store" target="_blank" rel="noreferrer">Atomics.store</a>、<a href="https://tc39.es/ecma262/multipage/memory-model.html#sec-synchronizes-with" target="_blank" rel="noreferrer">synchronizes-with</a>、<a href="https://tc39.es/ecma262/multipage/memory-model.html#sec-happens-before" target="_blank" rel="noreferrer">happens-before</a></p><h2 id="満杯や空を処理する方針を決める" tabindex="-1">満杯や空を処理する方針を決める <a class="header-anchor" href="#満杯や空を処理する方針を決める" aria-label="Permalink to &quot;満杯や空を処理する方針を決める&quot;">​</a></h2><p>キューに空きがないとき、この実装はキューが満杯であることを呼び出し元に返します。呼び出し元はその項目を保持し、受け取り側が読み進めたあとに再試行できます。例えば読み込み済みの結果を渡す処理なら、供給側を一時停止することで、受け取り側が処理できる量に合わせられます。どのデータを破棄してよいかは用途で変わります。音声出力でデータが間に合わない場合など、受け取り側が待てないときは、無音を出すなどの方針を別に決めます。<a href="/study/browser/worker-pool-backpressure.html">Workerプールのキューとバックプレッシャー</a>、<a href="/study/browser/streams-backpressure.html">Streams APIとバックプレッシャー</a></p><p>公開ページでは <code>ArrayBuffer</code> 上で <code>tryEnqueue()</code> と <code>tryDequeue()</code> を一操作ずつ動かし、枠とカーソルを確認できます。付属のローカル配信を使うと、二つのDedicated Workerが同じ実装を <code>SharedArrayBuffer</code> 上で動かします。Workerは満杯や空が返ったら処理をいったん譲って再試行します。再試行の回数は実行順によって変わります。<a href="/study/practice/browser/ring-buffer-observation.html">実践サンプル</a></p><p>音声のように出力を止めずに進める場合は、空のキューをどう扱うかも決めます。音声データを先にためる効果と、不足分を無音で埋める流れは<a href="/study/browser/audio-worklet-buffering.html">AudioWorkletと音声バッファ</a>で確認できます。</p>',18)])])}const g=r(s,[["render",i]]);export{m as __pageData,g as default};
